$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$modulePath = Join-Path $pkg "ahos\virtual_workforce.py"
$testPath = Join-Path $pkg "tests\test_virtual_workforce.py"
$backlogPath = Join-Path $pkg "AHOS_BACKLOG.json"
$python = Join-Path $root ".venv\Scripts\python.exe"

if (-not (Test-Path $backlogPath)) { throw "AHOS_BACKLOG.json not found." }
if (-not (Test-Path $python)) { throw "Python venv not found." }

[IO.File]::WriteAllBytes($modulePath, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($testPath, [Convert]::FromBase64String(""))

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
if (-not ($b.tasks | Where-Object { $_.id -eq "AHOS-023" })) {
    $b.tasks += [pscustomobject]@{
        id = "AHOS-023"
        title = "Create AHOS virtual workforce core and initial employee roster"
        status = "pending"
        risk = "low"
        authority = "B"
        requires_owner_approval = $false
        task = "Create the first real virtual-worker layer for AHOS: worker identities, roles, departments, capabilities, task slots, assignment/release, pause/resume, and per-worker AI budget gates. Add an initial multi-department virtual employee roster. Paid AI must be disabled by default. No external actions."
    }
    [IO.File]::WriteAllText(
        $backlogPath,
        ($b | ConvertTo-Json -Depth 12),
        (New-Object System.Text.UTF8Encoding($false))
    )
}

Write-Host "=== AHOS-023 VIRTUAL WORKFORCE CORE ==="
Write-Host "Creating virtual employee roster + worker registry."
Write-Host "NO network calls. NO OpenAI API calls. Paid AI disabled by default."

$oldPythonPath = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg
    & $python -m pytest -q
    $testExit = $LASTEXITCODE
} finally {
    Pop-Location
    $env:PYTHONPATH = $oldPythonPath
}
if ($testExit -ne 0) { throw "AHOS-023 tests failed." }

$b = Get-Content $backlogPath -Raw | ConvertFrom-Json
$t = $b.tasks | Where-Object { $_.id -eq "AHOS-023" } | Select-Object -First 1
$t.status = "completed"
if ($t.PSObject.Properties.Name -contains "completed_at") {
    $t.completed_at = [DateTime]::UtcNow.ToString("o")
} else {
    $t | Add-Member -NotePropertyName completed_at -NotePropertyValue ([DateTime]::UtcNow.ToString("o"))
}
[IO.File]::WriteAllText(
    $backlogPath,
    ($b | ConvertTo-Json -Depth 12),
    (New-Object System.Text.UTF8Encoding($false))
)

git -C $ws add ahos_core/ahos/virtual_workforce.py ahos_core/tests/test_virtual_workforce.py ahos_core/AHOS_BACKLOG.json
git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" commit -m "feat(ahos): add virtual workforce core"
if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

git -C $ws push origin HEAD
if ($LASTEXITCODE -ne 0) { throw "git push failed." }

Write-Host ""
Write-Host "=== AHOS-023 COMPLETE ==="
Write-Host "Full AHOS tests: PASS"
Write-Host "Backlog: AHOS-023 -> completed"
Write-Host "Git push: PASS"
Write-Host "Virtual workers created: 12"
Write-Host "Paid AI default: OFF"
Write-Host "Network calls: 0"
Write-Host "OpenAI API calls: 0"
